def handle(app, svc):
    resp = svc.apply(app)
    # API v2 response: {"api_version": 2, "result": {"outcome": ..., "credit_limit": <int>}}
    result = resp.get("result", {})
    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit", 0) or 0

    # Network referral rule: self_employed with requested_limit > 7000 -> manual review
    # (unless already declined, which stays a decline)
    if (app.get("employment") == "self_employed"
            and app.get("requested_limit", 0) > 7000
            and outcome != "declined"):
        return {"action": "queue_review", "limit": 0}

    if outcome == "approved":
        return {"action": "issue", "limit": credit_limit}
    elif outcome == "declined":
        return {"action": "decline", "limit": 0}
    elif outcome == "manual_review":
        return {"action": "queue_review", "limit": 0}
    else:
        return {"action": "queue_review", "limit": 0}

